mapper.update:
UPDATE games 
SET is_cancelled = #{isCanceled},
    is_ended = #{isEnded}
WHERE stadium = #{stadium, typeHandler=com.ssafy.ticket_backend.handler.StadiumTypeHandler}
  AND DATE(game_datetime) = DATE(#{gameDateTime})
  AND home_team = #{homeTeam, typeHandler=com.ssafy.ticket_backend.handler.BaseballTeamsTypeHandler}
  AND away_team = #{awayTeam, typeHandler=com.ssafy.ticket_backend.handler.BaseballTeamsTypeHandler}
